import numpy as np,json
from PIL import Image
from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=['front'],video='frames');cs=o.meta['cameras']
for c in ['front','left','right','topview']:
 im=np.array(Image.open('/app/output/initial_'+c+'.png')).astype(int);d=np.load('/app/output/depth_'+c+'.npy').astype(float).squeeze()
 mask=(im[:,:,2]>im[:,:,0]*1.5)&(im[:,:,2]>im[:,:,1]*1.2)&(im[:,:,2]>75)
 yy,xx=np.where(mask);x=int(np.median(xx));y=int(np.median(yy));z=d[y,x]
 # reconstruct camera matrices from static saved output? only front from obs; formulas hardcode from above
 if c=='front': trans=np.array([.034,1.949038,.8]); R=np.array([[-1,0,0],[0,-.5,.8660254],[0,.8660254,.5]])
 if c=='left': trans=np.array([-1.299038,.684,.8]);R=np.array([[0,.5,-.8660254],[-1,0,0],[0,.8660254,.5]])
 if c=='right': trans=np.array([1.299038,.616,.8]);R=np.array([[0,-.5,.8660254],[1,0,0],[0,.8660254,.5]])
 if c=='topview': trans=np.array([-.034,.5,1.5]);R=np.eye(3)
 p=trans+R@np.array([(x-160)/289.7056*z,-(y-120)/289.7056*z,-z]);print(c,p)
